#!/usr/bin/env python3
"""Read-only check: which Friend-Message:1 commits are not yet published on main."""
import re
import subprocess

CWD = "/home/runner/work/friend-joey"


def run(*args):
    return subprocess.run(args, cwd=CWD, capture_output=True, text=True, check=True).stdout


def published_map():
    files = run("git", "ls-tree", "-r", "--name-only", "origin/main").split()
    episodes = [p for p in files if re.fullmatch(r"S\d+/E\d+\.md", p)]
    pub = {}
    for ep in episodes:
        text = run("git", "show", "origin/main:" + ep)
        for m in re.finditer(r"^Source: friend/(\w+) @ ([0-9a-f]{40})\s*$", text, re.M):
            pub[m.group(2)] = (ep, m.group(1))
    return pub, episodes


def utterance_commits():
    out = []
    for b in ["rachel", "monica", "phoebe", "joey", "chandler", "ross"]:
        log = run("git", "log", "--format=%H\x1f%cI\x1f%B\x1e", "origin/friend/" + b)
        for rec in log.split("\x1e"):
            rec = rec.strip()
            if not rec:
                continue
            parts = rec.split("\x1f", 2)
            if len(parts) != 3:
                continue
            sha, when, body = parts
            if not re.search(r"^Friend-Message: 1$", body, re.M):
                continue
            m = re.search(r"^Episode: (S\d+/E\d+)$", body, re.M)
            out.append((sha, when, b, m.group(1) if m else "UNKNOWN"))
    return out


def main():
    pub, episodes = published_map()
    utt = utterance_commits()
    missing = [u for u in utt if u[0] not in pub]
    print("episodes on main:", len(episodes), "published entries:", len(pub))
    print("utterance commits on branches:", len(utt), "| not yet published:", len(missing))
    for sha, when, b, ep in sorted(missing):
        print("  MISSING", ep, when, "friend/" + b, sha)


if __name__ == "__main__":
    main()
